def ev(file,needle,n=6):
 lines=(ROOT/file).read_text(encoding='utf8').splitlines()
 if file=='data_dicts_compact_lines.py' and '"кто": "' in needle:
  name=needle.split('"кто": "')[1].rstrip('"');i=next(i for i,l in enumerate(lines) if '"кто":"'+name+'"' in l.replace(' ','')) if ' ' not in name else next(i for i,l in enumerate(lines) if re.search(r'"кто"\s*:\s*"'+re.escape(name)+r'"',l))
 else:i=next(i for i,l in enumerate(lines) if needle in l or needle.replace('"',"'") in l)
 return {'label':f'{file}:{i+1}','detail':needle,'code':'\n'.join(lines[i:i+n])}
def db(table,ids,detail):return {'label':f'Globals/{table} · {ids}','detail':detail}
def manual(page,detail):return {'label':f'DII Manual.pdf · страница PDF {page}','detail':detail}
